SELECT A.SEQ_NO, B.BOK_DETAIL_ID, 3 AS PRIORITY, B.BUSI_ID, A.CAPI_INCOME_FEATURE, A.INCOME_TYPE, A.TAXABLE_SIGN, A.TAX_RATE, A.EFF_DATE, A.FEE_TYPE FROM TAX_TAXABLE_INFO A INNER JOIN BOK_DETAIL_ID B ON A.ASSET_ID = B.BUSI_ID INNER JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.BUSI_ID LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID = B.BUSI_ID LEFT JOIN FIN_TRADE_PRODUCT E ON E.FINPROD_ID = B.BUSI_ID WHERE ( NVL(E.CAPI_INCOME_FEATURE, D.CAPI_INCOME_FEATURE) = A.CAPI_INCOME_FEATURE OR A.CAPI_INCOME_FEATURE IS NULL ) AND (B.BOK_DETAIL_ID IN
null) OR B.BOK_DETAIL_ID in (
#{item}
)
AND SCH_ID IN ( SELECT SCHEME_ID FROM BOK_BOOKSET_PLAN WHERE BOOKSET_ID = #{booksetId} AND SCHEME_TYPE = #{schemeType} ) AND A.EFF_DATE <= #{effDate}
UNION ALL SELECT A.SEQ_NO, B.BOK_DETAIL_ID, 1 AS PRIORITY, B.BUSI_ID, A.CAPI_INCOME_FEATURE, A.INCOME_TYPE, A.TAXABLE_SIGN, A.TAX_RATE, A.EFF_DATE, A.FEE_TYPE FROM TAX_VAT_SCHEDULE A INNER JOIN FIN_PRODUCT_TYPE C ON A.ASSET_CLASSIFY = C.TYPE_3 INNER JOIN BOK_DETAIL_ID B ON C.FINPROD_ID = B.BUSI_ID LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID = B.BUSI_ID LEFT JOIN FIN_TRADE_PRODUCT E ON E.FINPROD_ID = B.BUSI_ID WHERE ( NVL(E.CAPI_INCOME_FEATURE, D.CAPI_INCOME_FEATURE) = A.CAPI_INCOME_FEATURE OR A.CAPI_INCOME_FEATURE IS NULL ) AND B.BOK_DETAIL_ID IN
#{item}
AND SCH_ID IN ( SELECT SCHEME_ID FROM BOK_BOOKSET_PLAN WHERE BOOKSET_ID = #{booksetId} AND SCHEME_TYPE = #{schemeType} ) AND A.EFF_DATE <= #{effDate}

