        DELETE FROM TAX_BOK_DETAIL a
        WHERE EXISTS(
			SELECT 1
            FROM BOK_BATCH_TASK_TODO B
            WHERE
              	B.BOOKSET_ID =  A.BOOKSET_ID
              	AND B.SEQ_NO = #{seqNo}
				AND B.BOOKSET_DATE = #{BOOKSET_DATE}
                AND B.TASK_ID = #{taskId}
        	)
        	AND a.BOOKSET_DATE >= #{BOOKSET_DATE}

        DELETE
        FROM TAX_BOK_BALANCE a
        WHERE EXISTS(
			SELECT 1
            FROM BOK_BATCH_TASK_TODO B
            WHERE
              	B.BOOKSET_ID =  A.BOOKSET_ID
              	AND B.SEQ_NO = #{seqNo}
				AND B.BOOKSET_DATE = #{BOOKSET_DATE}
                AND B.TASK_ID = #{taskId}
        	)
        	AND a.BOOKSET_DATE >= #{BOOKSET_DATE}

        DELETE FROM TAX_BOK_BALANCE_SUM a
        WHERE EXISTS(
			SELECT 1
            FROM BOK_BATCH_TASK_TODO B
            WHERE
              	B.BOOKSET_ID =  A.BOOKSET_ID
              	AND B.SEQ_NO = #{seqNo}
				AND B.BOOKSET_DATE = #{BOOKSET_DATE}
                AND B.TASK_ID = #{taskId}
        	)
        	AND a.BOOKSET_DATE >= #{BOOKSET_DATE}

        DELETE FROM TAX_DEDUCTED_BALANCE a
        WHERE EXISTS(
			SELECT 1
            FROM BOK_BATCH_TASK_TODO B
            WHERE
              	B.BOOKSET_ID =  A.BOOKSET_ID
              	AND B.SEQ_NO = #{seqNo}
				AND B.BOOKSET_DATE = #{BOOKSET_DATE}
                AND B.TASK_ID = #{taskId}
        	)
        	AND a.BOOKSET_DATE >= #{BOOKSET_DATE}
